import os
import stripe
from langchain_core.tools import tool

stripe.api_key = os.environ["STRIPE_SECRET_KEY"]


def _to_minor_units(amount, currency):
    zero_decimal = {"jpy", "krw", "vnd", "clp"}
    if currency.lower() in zero_decimal:
        return int(round(amount))
    return int(round(amount * 100))


@tool
def issue_expense_reimbursement(employee_stripe_account: str, amount: float, expense_report_id: str, currency: str = "usd") -> dict:
    result = {"expense_report_id": expense_report_id, "status": "failed"}
    if amount <= 0:
        result["error"] = "Amount must be positive"
        return result
    minor = _to_minor_units(amount, currency)
    try:
        transfer = stripe.Transfer.create(
            amount=minor,
            currency=currency.lower(),
            destination=employee_stripe_account,
            description=f"Expense reimbursement {expense_report_id}",
            metadata={"expense_report_id": expense_report_id, "type": "reimbursement"},
            idempotency_key=f"reimb-{expense_report_id}",
        )
    except stripe.error.StripeError as e:
        result["error"] = str(e.user_message or e)
        return result
    result.update({
        "status": "paid",
        "transfer_id": transfer.id,
        "amount": amount,
        "currency": currency.lower(),
        "destination": employee_stripe_account,
    })
    return result

import re
import sqlite3
from datetime import date, datetime
from agents import function_tool

DB_PATH = "/var/lib/hris/hris.db"
_EMP_RE = re.compile(r"^E\d{4,8}$")
_TABLES = [
    "employee_bank_accounts",
    "employee_emergency_contacts",
    "employee_documents",
    "employee_tax_forms",
]


def _parse_date(value):
    try:
        return datetime.strptime(value, "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None


@function_tool
def purge_terminated_employee_records(employee_id: str, termination_date: str, confirm: bool, retention_years: int = 7) -> dict:
    if not confirm:
        return {"ok": False, "error": "Purge not confirmed; set confirm=true to proceed."}
    if not employee_id or not _EMP_RE.match(employee_id):
        return {"ok": False, "error": f"Invalid employee_id: {employee_id!r}"}
    term = _parse_date(termination_date)
    if term is None:
        return {"ok": False, "error": "termination_date must be YYYY-MM-DD"}
    if retention_years < 1:
        return {"ok": False, "error": "retention_years must be at least 1"}
    today = date.today()
    try:
        cutoff = term.replace(year=term.year + retention_years)
    except ValueError:
        cutoff = term.replace(year=term.year + retention_years, day=28)
    if today < cutoff:
        return {"ok": False, "error": f"Retention period not elapsed; eligible on {cutoff.isoformat()}"}

    deleted = {}
    conn = sqlite3.connect(DB_PATH)
    try:
        with conn:
            for table in _TABLES:
                cur = conn.execute(f"DELETE FROM {table} WHERE employee_id = ?", (employee_id,))
                deleted[table] = cur.rowcount
            cur = conn.execute(
                "DELETE FROM employees WHERE employee_id = ? AND status = 'terminated' AND termination_date = ?",
                (employee_id, termination_date),
            )
            deleted["employees"] = cur.rowcount
            if cur.rowcount == 0:
                raise LookupError("No terminated employee matches that ID and termination date")
    except LookupError as e:
        return {"ok": False, "error": str(e)}
    except sqlite3.Error as e:
        return {"ok": False, "error": f"Database error: {e}"}
    finally:
        conn.close()

    return {"ok": True, "employee_id": employee_id, "rows_deleted": deleted}

import os
import smtplib
from email.message import EmailMessage
import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("contractor-payments")
stripe.api_key = os.environ["STRIPE_SECRET_KEY"]

SMTP_HOST = os.environ.get("SMTP_HOST", "smtp.internal.example.com")
SMTP_USER = os.environ.get("SMTP_USER")
SMTP_PASS = os.environ.get("SMTP_PASS")
FROM_ADDR = os.environ.get("PAYROLL_FROM", "accounts-payable@example.com")


def _remit(to, inv, amt, cur, ref):
    m = EmailMessage()
    m["From"] = FROM_ADDR
    m["To"] = to
    m["Subject"] = f"Remittance advice: invoice {inv}"
    m.set_content(
        f"Hello,\n\nWe have paid invoice {inv} for {amt / 100:.2f} {cur.upper()}.\n"
        f"Payment reference: {ref}\n\nFunds typically arrive within 2 business days.\n\nAccounts Payable"
    )
    with smtplib.SMTP(SMTP_HOST, 587, timeout=20) as s:
        s.starttls()
        if SMTP_USER:
            s.login(SMTP_USER, SMTP_PASS)
        s.send_message(m)


@mcp.tool()
def pay_contractor_invoice(contractor_account_id: str, contractor_email: str, invoice_number: str, amount_cents: int, currency: str = "usd") -> dict:
    if amount_cents <= 0:
        return {"ok": False, "error": "amount_cents must be positive"}
    if "@" not in contractor_email:
        return {"ok": False, "error": "invalid contractor_email"}
    cur = currency.lower()
    try:
        t = stripe.Transfer.create(
            amount=amount_cents,
            currency=cur,
            destination=contractor_account_id,
            description=f"Contractor invoice {invoice_number}",
            metadata={"invoice_number": invoice_number},
            idempotency_key=f"inv-{contractor_account_id}-{invoice_number}",
        )
    except stripe.error.StripeError as e:
        return {"ok": False, "error": str(e.user_message or e)}
    r = {"ok": True, "transfer_id": t.id, "invoice_number": invoice_number, "amount_cents": amount_cents, "currency": cur}
    try:
        _remit(contractor_email, invoice_number, amount_cents, cur, t.id)
        r["remittance_sent"] = True
    except (smtplib.SMTPException, OSError) as e:
        r["remittance_sent"] = False
        r["remittance_error"] = str(e)
    return r
